const s=[{id:"identity-gollwitzer",title:"I01 · Gollwitzer & Sheeran · 2006 · If-then plans and goal attainment",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"Across 94 independent tests involving 8,461 participants, if-then plans improved goal attainment on average (d = 0.65).",limitation:"83 experimental and 11 correlational tests covered varied goals and methods. This does not validate a branded habit package or the exact ODA plan."},{id:"identity-harkin",title:"I02 · Harkin et al. · 2016 · Monitoring goal progress",url:"https://doi.org/10.1037/bul0000025",type:"research",finding:"Across 138 randomized studies, monitoring interventions improved goal attainment on average (d = 0.40). A bias-adjusted estimate was smaller (d = 0.19).",limitation:"Goals and recording methods varied. Moderator findings do not require public disclosure. This receipt and next-day review were not tested."},{id:"identity-cole",title:"I03 · Cole et al. · 2021 · Mental simulation and behavior change",url:"https://doi.org/10.3758/s13423-021-01880-6",type:"research",finding:"Across 94 randomized studies, mental simulation had an average behavioral effect (g = 0.49). The overall comparison between simulation subtypes was not significant.",limitation:"Most samples were students; reporting and subgroup sizes limit certainty. This does not establish a winning imagery subtype or an identity meditation effect."},{id:"identity-lally",title:"I04 · Lally et al. · 2010 · How are habits formed?",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"In 39 good-fitting models, estimated time to 95% of the automaticity plateau had a median of 66 days and range of 18-254 days.",limitation:"96 volunteers entered; behavior was observed for 84 days. Longer estimates were extrapolated. This was not an identity-change deadline or a test of a two-day-gap rule."},{id:"identity-habit-times",title:"I05 · Singh et al. · 2024 · Habit formation review",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"A review of 20 health-behavior studies found wide variation in habit formation. Only four studies reported formation times.",limitation:"11 studies had high risk of bias. Pre/post habit-score improvement is not a randomized causal effect. No universal formation deadline is supported."},{id:"identity-wood-runger",title:"I06 · Wood & Rünger · 2016 · Psychology of habit",url:"https://doi.org/10.1146/annurev-psych-122414-033417",type:"research",finding:"The review describes habits developing through repeated responses in recurring contexts. Habitual and deliberate processes can operate together.",limitation:"A narrative review, with no pooled effect. It does not classify every mood or thought as a habit, or prove that changing context always beats effort."},{id:"identity-wood-everyday",title:"I07 · Wood, Quinn & Kashy · 2002 · Habits in everyday life",url:"https://doi.org/10.1037/0022-3514.83.6.1281",type:"research",finding:"In two student diary samples, 35% and 43% of reported behaviors met an almost-daily, same-location habit definition.",limitation:"The samples contained 70 and 209 students. These percentages are not population estimates or mind-wandering prevalence. Diary assessment did not test an identity intervention."},{id:"identity-lieberman",title:"I10 · Lieberman et al. · 2007 · Putting feelings into words",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"In 30 adults viewing faces, emotion-word labeling produced lower amygdala activation than gender-name labeling.",limitation:"A small laboratory brain-imaging study, not a measure of everyday emotional recovery. It does not establish that naming your own distress makes it smaller."},{id:"identity-breines",title:"I11 · Breines & Chen · 2012 · Self-compassion and improvement motivation",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Four short experiments found support for immediate improvement motivation after compassionate responses. One experiment found more study time than a no-intervention condition.",limitation:"Mainly student and online samples; effects differed by comparison. Test scores did not significantly differ in that study. Lasting identity change was not established."},{id:"identity-clear-identity",title:"I15 · James Clear · Identity-based habits",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear frames small actions as evidence for a desired identity. The action-as-vote idea is a practitioner metaphor.",limitation:"The author article is not a trial, and its publication year was not established. Identity-first superiority and the never-miss-twice rule are not verified scientific laws."},{id:"identity-task-belief",title:"I17 · Bandura · 1977 · Self-efficacy theory",url:"https://doi.org/10.1037/0033-295X.84.2.191",type:"research",finding:"The framework describes perceived capability for a specific task, informed by mastery, observing others, persuasion, and physiological information.",limitation:"A theoretical synthesis, not a pooled intervention estimate. Capability beliefs do not measure personal worth or verify an identity-vote method."},{id:"identity-activity-identity",title:"I19 · Rhodes et al. · 2025 · Physical-activity identity interventions",url:"https://doi.org/10.1080/17437199.2024.2412996",type:"research",finding:"Across 40 experimental or quasi-experimental effects involving 4,939 adults, physical-activity identity changed a little on average (g = 0.18).",limitation:"Behavior effects came from a different 30-effect subsample and were heterogeneous. The review does not establish that identity caused behavior change or generalize to whole-person transformation."},{id:"identity-motor-rehearsal",title:"I18 · Toth et al. · 2020 · Mental practice and task performance",url:"https://doi.org/10.1016/j.psychsport.2020.101672",type:"research",finding:"The review of 37 studies reported a small bias-adjusted mental-practice effect on motor or task performance (r = .131).",limitation:"The opened abstract did not establish participant total or confidence interval. Motor-task evidence does not demonstrate identity change, healing, or emotional biology effects."}],e={schemaVersion:2,revision:2,id:"identity-1",courseId:"identity",locale:"en",title:"Still scrolling? Find your changeable moment",goal:"Choose one recurring cue and try a useful response that serves your week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another afternoon lost to the same distraction? Find one moment you can change.",reason:{id:"identity-1-reason",label:"What does this pattern protect now and postpone later?",kind:"text",maxLength:160,optional:!0,suggestions:["Finish work without another late evening","Make room for my creative work","Give people my attention"]},why:{id:"identity-1-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A familiar setting can cue a familiar action, even after your priorities change. Habit research separates that repeated response from your whole personality. “After lunch, I scroll before starting” names a pattern. “I am lazy” gives you no moment to work with.","Choose one ordinary cue and one useful alternative. Notice what the old response offers now and what it postpones. Then try the alternative once. This course keeps improving that same experiment. You can start with a small act without rejecting who you are or promising a new personality."],example:{title:"Leyla's first report sentence",text:"At 1:30, Leyla returns to her desk and reaches for her phone before writing a report. She wants fewer late evenings. She puts the phone aside and writes one rough opening sentence instead. The wording is awkward, and she later scrolls again. Her record says what she did at the cue, without calling the afternoon a transformation."}},move:{invitation:"Choose one familiar cue. Try a response that does something useful for your chosen direction.",instructions:["Name the cue and the actual behavior you will try.","Record what you did when that cue appeared."],prompts:[],suggestions:{action:["Write one usable sentence","Ask one attentive question","Complete one small practical step"],minimum:["Add one sentence to my draft","Listen to one full answer","Finish one useful part"],cue:["When I return after lunch","When I put my bag down","At my usual evening start"],place:["At my usual work surface","In our safe conversation space"],fallback:["Dictate the sentence instead","Use my next available cue","Ask for practical assistance"],observation:["Whether I wrote the sentence","What I did at the cue","What the old response postponed"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one usable sentence",minimum:"Add one sentence to my draft",minutes:2,cueHint:"When I return after lunch",placeHint:"At my usual work surface",obstacleHint:"The familiar distraction is easier to reach.",fallbackHint:"Dictate the sentence instead",observationHint:"Whether I wrote the sentence"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-1-decision",scenario:"Leyla planned to write after lunch but scrolled. She has five minutes and the report open.",question:"Which move starts a useful experiment?",options:[{id:"identity-1-redesign-day",text:"Build a stricter afternoon schedule, then begin the report once the new schedule is complete.",feedback:"A schedule may help later. Right now it adds preparation before an available attempt. Name the lunch cue, write one useful sentence, and record what gets in the way."},{id:"identity-1-test-cue",text:"Name what happened after lunch, then write one report sentence and record the cue.",feedback:"This tests a response in the real setting. The sentence does useful work, and the note identifies the cue. One attempt provides information without proving a whole personality change."},{id:"identity-1-change-break",text:"Move tomorrow’s writing before lunch and use today’s remaining five minutes to review the new plan.",feedback:"Changing a cue can help if lunch timing is the problem. Here an actual five-minute attempt is still available. Test one sentence and record the cue before deciding that a new schedule fits better."}],bestOptionId:"identity-1-test-cue"}},carry:{takeaway:"Change one response in one setting. Let the record describe what happened.",followUp:{questionId:"identity-1-return",question:"When your chosen cue appeared, what did you do instead of the familiar response?",observationPrompt:"Name your response at the cue, or note that the cue never occurred.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"A pattern is smaller than a person",paragraphs:["Wood and Rünger’s review describes habits as repeated responses associated with recurring contexts [I06]. A setting can call up a familiar response alongside deliberate choices. That is a narrower claim than saying every thought, mood, or difficult day is an automatic program. This lesson asks about one observable behavior, not an “old self” that must be removed.","The diary research used student samples of 70 and 209 people [I07]. Respectively, 35% and 43% of their reports met an almost-daily, same-location definition of habit. Those figures do not describe all adults, and they are not percentages of time spent mind-wandering. Sampling behavior was assessment, not a demonstrated identity treatment.","ODA’s cue-and-response note is a teaching adaptation. Keep only the detail useful for your next choice. An unchanged mood or imperfect afternoon does not invalidate an accurately reported attempt."]},{heading:"Make the alternative consequential",paragraphs:["Gollwitzer and Sheeran’s review combined 94 independent tests involving 8,461 participants [I01]. It found an average goal-attainment benefit from specific if-then plans. The evidence included 83 experimental and 11 correlational tests, with varied goals and methods. It does not establish that this particular ODA sequence changes identity.","For this experiment, connect a recognizable event with a feasible response: when you return after lunch, write one useful report sentence. Specify a cue you actually encounter. Choose an alternative that contributes to your direction, rather than simply opening an app or arranging supplies. Those may be preparation, but the practice should be named accurately.","There is no requirement to interrupt every familiar behavior. Keep routines that serve your life. If the setting calls for safety, rest, or assistance, choose that response deliberately. Review this one attempt before adding another system."]}],sourceIds:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"]}},t={schemaVersion:2,revision:2,id:"identity-2",courseId:"identity",locale:"en",title:"Worry still here? Choose your response anyway",goal:"Use your same cue to do the useful action while an ordinary feeling remains.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Waiting for worry to leave before you start? Give your chosen action a safe chance.",reason:{id:"identity-2-reason",label:"What is waiting for this feeling costing your direction?",kind:"text",maxLength:160,optional:!0,suggestions:["Start while ordinary worry remains","Protect an evening I value","Respond without hiding my needs"]},why:{id:"identity-2-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your cue and action. A familiar feeling is something to notice, not proof of a fixed personality. Naming feelings has a narrow research basis: one small study found a changed brain response when people labeled emotions on faces. It did not test whether your own worry disappears.","Use a label as a description: “Worry is here.” Check whether it points to a real need, then choose your response. You may write your sentence while worried, or seek help if the concern needs action. The useful act counts without a calmer feeling afterward."],example:{title:"Leyla's worried start",text:"After lunch on Thursday, Leyla feels worried about the same report. She checks that she has the required figures, names the worry, and writes her next usable sentence. She still wants to recheck everything. She records the sentence and that the worry stayed. She has practiced writing, not proved that the feeling is a habit."}},move:{invitation:"Keep your experiment. Name an ordinary feeling if useful, then do the chosen response.",instructions:["Check for a real problem before treating this as ordinary worry.","Let the feeling remain while you try."],prompts:[],suggestions:{action:["Write my next usable sentence","Listen while ordinary guilt remains","Ask for the help I need"],minimum:["Add one sentence to my draft","Ask one attentive question","Send one practical help request"],cue:["When worry appears at my cue","After checking the urgent need","At my next safe opening"],place:["At my usual work surface","In a safe shared space"],fallback:["Dictate one useful sentence","Address the real problem first","Choose support instead"],observation:["Whether I acted while worry remained","Whether there was a real unmet need","The actual request or response"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write my next usable sentence",minimum:"Add one sentence to my draft",minutes:2,cueHint:"When worry appears at my cue",placeHint:"At my usual work surface",obstacleHint:"I want the feeling to disappear before acting.",fallbackHint:"Dictate one useful sentence",observationHint:"Whether I acted while worry remained"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-2-decision",scenario:"Leyla has five minutes. Her figures match the approved table, and her sentence makes no new calculation. She still feels worried.",question:"Which response fits this moment?",options:[{id:"identity-2-recheck",text:"Recheck the figures once more so she can feel more certain before writing the sentence.",feedback:"Another check can help when information is missing. The needed figures are already checked here. Rechecking postpones the available writing attempt without making a calmer feeling a reliable starting cue."},{id:"identity-2-provisional-check",text:"Draft a provisional sentence and ask a colleague to verify its figure before keeping the line in the report.",feedback:"A provisional line and second check help when a figure is uncertain. Here the approved table already supports the sentence. Requiring another reply delays keeping a usable line without addressing a known gap."},{id:"identity-2-act-with-feeling",text:"Name the worry, write one usable sentence, and record whether the concern needed further action.",feedback:"This preserves the feeling and checks its meaning without giving it an automatic veto. The sentence is the practice. If a real concern appears, her next response can be practical help."}],bestOptionId:"identity-2-act-with-feeling"}},carry:{takeaway:"A feeling can remain while you choose a useful, safe response.",followUp:{questionId:"identity-2-return",question:"Did the feeling remain during your action, and did it point to a real unmet need?",observationPrompt:"Name any feeling that remained and any need it revealed, or note no clear need.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"What labeling actually measured",paragraphs:["Lieberman and colleagues studied 30 healthy adults looking at emotional faces in a brain scanner [I10]. Choosing an emotion word produced lower amygdala activation than choosing a gender-matched name. That is a difference in a laboratory brain measure, not a finding that naming your own distress makes it smaller or improves mood for weeks.","ODA uses a short feeling label as optional description. The study did not test this cue, your chosen behavior, or a course about identity. Skip labeling if it adds nothing, and avoid turning every emotion into something you must correct. Grief, anger about unfairness, and fear in danger can deserve a different response.","Bring the observation back to the same action. Did you do it, did you need assistance, or did a real problem change the plan? A record can hold a difficult feeling and a useful behavior without claiming one caused the other."]},{heading:"Support without removing accountability",paragraphs:["Breines and Chen tested compassionate responses in four short experiments, mainly with student or online samples [I11]. Some outcomes supported immediate improvement motivation. In one study, participants spent more time studying after a difficult test than those receiving no intervention. Their later test scores did not significantly differ, and comparison with a self-esteem condition was only marginal.","That evidence does not prove lasting identity change or universal superiority of kindness. It does challenge the assumption that a harsh response is always needed before trying again. This lesson’s instruction to describe a feeling and continue a chosen action is an ODA adaptation, not the tested compassionate-writing procedure.","Use a fair response that keeps responsibility visible. A missing skill calls for learning; an unmet need may call for help. You can act without insulting yourself and can pause without calling the pause a failed personality."]}],sourceIds:["identity-lieberman","identity-breines"]}},a={schemaVersion:2,revision:2,id:"identity-3",courseId:"identity",locale:"en",title:"Caught yourself late? Make the next move useful",goal:"Return to your chosen action after a distraction, or repair a response that caused harm.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Already scrolling or already snapped? The next sentence can still do useful work.",reason:{id:"identity-3-reason",label:"What needs a return or repair in this same experiment?",kind:"text",maxLength:160,optional:!0,suggestions:["Return before the afternoon disappears","Repair a sharp response","Keep my useful action available"]},why:{id:"identity-3-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Noticing a distraction is different from returning. Keep your chosen cue and action. Add a late-catch response: “If I notice I have drifted, I will do my useful minimum.” Specific cue-and-action plans have improved goal attainment on average in research.","If your response hurt someone, a private catch is not the repair. In a safe setting, acknowledge your part and restart one sentence. If nobody was harmed, return to the task. Record the response, not just notices. You can change the next act without declaring the day ruined."],example:{title:"Leyla's late catch",text:"At 1:42, Leyla notices she has spent twelve minutes scrolling instead of writing. She closes the feed and adds one useful sentence to her report. Later she notices an abrupt message she sent her colleague. She sends a brief correction of her tone. Neither act erases the lost time, but both are specific responses she can record."}},move:{invitation:"Keep your action. Choose what you will do when you notice the pattern late.",instructions:["Return to the useful minimum, or repair your own harmful response.","Record what followed the catch."],prompts:[],suggestions:{action:["Return to my useful sentence","Restart one sentence respectfully","Repair my own sharp message"],minimum:["Add one useful sentence now","Acknowledge and restate one sentence","Send one clear repair message"],cue:["When I notice I am scrolling","When I hear my sharp tone","After a safe interruption ends"],place:["At my usual work surface","In the safe message thread"],fallback:["Use a shorter useful sentence","Choose a safer repair channel","Ask for help restarting"],observation:["What I did after noticing","Whether I made the actual repair","Where I noticed the pattern"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Return to my useful sentence",minimum:"Add one useful sentence now",minutes:2,cueHint:"When I notice I am scrolling",placeHint:"At my usual work surface",obstacleHint:"I notice only after the distraction has started.",fallbackHint:"Use a shorter useful sentence",observationHint:"What I did after noticing"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-3-decision",scenario:"During a safe discussion, Leyla snaps at a colleague. She notices her tone while they are still talking.",question:"What best completes the interruption?",options:[{id:"identity-3-repair",text:"Acknowledge the sharp sentence and restate her point respectfully while the conversation is still open.",feedback:"This makes the catch consequential. Leyla takes responsibility for her own tone and practices a different response. The colleague does not have to forgive her for the repair attempt to be real."},{id:"identity-3-private-catch",text:"Pause privately and record the catch, then focus on speaking more patiently in their next discussion.",feedback:"Noticing provides information, but the sharp sentence has already affected this conversation. Where repair is safe and appropriate, a brief acknowledgment and restatement address the current effect rather than only tomorrow’s behavior."},{id:"identity-3-full-explanation",text:"Explain why the deadline pressure caused her tone, then return to the work discussion without revisiting it.",feedback:"Context may explain the strain and may need changing. It does not replace a repair for her own response. Acknowledge the tone first, then discuss workload without making agreement a condition."}],bestOptionId:"identity-3-repair"}},carry:{takeaway:"A catch becomes useful when you return, repair, or choose a safer response.",followUp:{questionId:"identity-3-return",question:"When did you notice the pattern, and what actual return or repair followed?",observationPrompt:"Note when you noticed, then any return, repair, protection, or no occasion.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"A cue can include late noticing",paragraphs:["Implementation intentions connect a specific situation with a chosen response. Gollwitzer and Sheeran’s synthesis found an average benefit for goal attainment across 94 independent tests [I01]. Goals, delivery, and study methods varied. It does not validate a particular pause word, breathing sequence, or number of daily catches.","This lesson adds late noticing as another possible situation: if you notice scrolling has begun, write your chosen useful sentence. The response is still the same course experiment. A silent cue word is optional shorthand, not the active behavior you are trying to build. No breath or calm feeling is required before returning.","Wood and Rünger describe habits operating alongside deliberate processes [I06]. That leaves room for an intentional response within an imperfect routine. It does not mean every distraction was a habit. Describe what you observed and test whether this cue is recognizable in your actual setting."]},{heading:"Notice, then respond to the consequence",paragraphs:["A record should distinguish noticing, returning, and repairing. Harkin and colleagues reviewed 138 randomized progress-monitoring studies [I02]. Monitoring interventions improved goal attainment on average, though a bias-adjusted estimate was smaller. The review does not establish that counting catches alone changes your relationships or that every private note needs to be shared.","For this ODA adaptation, record the behavior that followed your notice. “I caught my sharp tone” and “I acknowledged it and restated my request” are different facts. If your original task was interrupted, record the useful part you resumed. If you caused no harm, an apology is not required.","Protection takes priority in an unsafe relationship. You do not owe contact, forgiveness, or an explanation to someone who threatens you. Choose a boundary or support step when it fits. Keep those acts named accurately rather than treating every pause as successful repair."]}],sourceIds:["identity-gollwitzer","identity-wood-runger","identity-harkin"]}},n={schemaVersion:2,revision:2,id:"identity-4",courseId:"identity",locale:"en",title:"Busy preparing? Make your next action real proof",goal:"Check that your minimum practices the behavior your direction needs, then do it once.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another polished plan, still no draft? Make one useful action the evidence.",reason:{id:"identity-4-reason",label:"Is this minimum building the skill or postponing it?",kind:"text",maxLength:160,optional:!0,suggestions:["Practice the work itself","Keep the minimum meaningful","Describe only what I actually did"]},why:{id:"identity-4-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your last attempt. James Clear calls actions “votes” for an identity. That is a metaphor, not a scientific law. You can use it without saying your identity must change first. The useful question is whether this action practices something your direction needs.","Opening a draft proves you opened it. Writing one usable sentence proves you wrote. Both can have a purpose, but name preparation as preparation. Keep the minimum small enough for your week and substantial enough to matter. After an actual attempt, describe only that evidence. “I wrote a sentence” needs no claim about permanent confidence."],example:{title:"Leyla's useful minimum",text:"On Friday, Leyla spends five minutes arranging headings but has written no report text. She checks her experiment and changes the minimum to one usable sentence under a heading. She writes it before stopping. The sentence needs editing. Her optional note says, “I wrote a sentence today,” rather than “I am now a disciplined person.”"}},move:{invitation:"Check your saved minimum. If it only prepares, name that honestly or choose actual practice.",instructions:["Do one useful unit of the behavior your direction needs.","Afterward, describe only the action you actually completed."],prompts:[],suggestions:{action:["Write one usable report sentence","Practice one actual skill attempt","Use one respectful repair sentence"],minimum:["Add one usable sentence","Complete one real practice attempt","Make one actual repair"],cue:["When I open my existing draft","At my next practice cue","When a safe repair is possible"],place:["In my actual draft","At the usual practice location"],fallback:["Dictate a usable sentence","Shrink the actual practice unit","Record preparation as preparation"],observation:["The actual behavior completed","Whether the minimum served my direction","What preparation still remains"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one usable report sentence",minimum:"Add one usable sentence",minutes:2,cueHint:"When I open my existing draft",placeHint:"In my actual draft",obstacleHint:"Preparation feels easier than the actual behavior.",fallbackHint:"Dictate a usable sentence",observationHint:"The actual behavior completed"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-4-decision",scenario:"Leyla has five tired minutes and wants report text. Her headings are ready; the next sentence's figure already matches its source.",question:"Which minimum does useful work now?",options:[{id:"identity-4-organize",text:"Arrange the notes into a clearer folder so tomorrow’s writing session starts with less friction.",feedback:"Organization can support later writing. Here the notes and headings are already ready, so more setup delays the skill Leyla wants to practice. Name it as preparation if she chooses it."},{id:"identity-4-write-unit",text:"Write one rough sentence in the real report, then decide whether stopping fits her capacity.",feedback:"This minimum practices the desired behavior and respects the time available. It proves one sentence was written, not that her identity changed. She can stop without making the sentence impressive."},{id:"identity-4-verify-support",text:"Recheck the cited figure against its source, then leave a verified note for tomorrow's sentence.",feedback:"Verification is useful when factual support is uncertain. This figure has already been checked, so repeating that preparation uses tonight's writing time. One rough supported sentence would advance the report now."}],bestOptionId:"identity-4-write-unit"}},carry:{takeaway:"Let your evidence name the behavior. Keep preparation and practice distinct.",followUp:{questionId:"identity-4-return",question:"What did your minimum actually demonstrate, and was it useful for your chosen direction?",observationPrompt:"Name the behavior your minimum demonstrated and whether it helped your direction.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"An identity metaphor has limits",paragraphs:["Clear’s author article presents a desired identity and small supporting actions as a practitioner framework [I15]. It is not a controlled trial proving identity-first change is required or superior. The familiar action-as-vote framing can be memorable without becoming a scientific explanation.","Bandura’s self-efficacy framework concerns perceived capability for a particular task [I17]. Mastery experiences are one source of that belief, alongside observation, persuasion, and physiological information. The framework does not turn one action into a measure of your worth or a verdict about your whole personality.","ODA’s optional evidence statement stays narrow: “I added a usable sentence” or “I made my request.” An untried plan and a correct quiz answer do not establish those behaviors. You may leave identity language out entirely while continuing the same practical experiment."]},{heading:"Behavior and identity are different outcomes",paragraphs:["Rhodes and colleagues reviewed 40 experimental or quasi-experimental effects involving 4,939 adults [I19]. Physical-activity identity changed a little on average, with an effect of g = 0.18. A 30-effect behavior subsample showed a larger average activity effect, but the samples and outcomes differ. Those numbers do not prove identity caused behavior change.","The studies concern physical activity, with heterogeneous results and possible publication bias. They do not validate broad personality transformation, Clear’s vote method, or this report-writing experiment. Difficulty also does not automatically show that a goal matters enough to pursue. It can reveal a missing skill, insufficient resources, or a need to revise the plan.","Use the record to decide what your minimum contributes. Keep a small unit when it fits capacity, increase it only by choice, or change an unsuitable goal. The aim is useful practice in your life, not collecting symbolic votes."]}],sourceIds:["identity-clear-identity","identity-task-belief","identity-activity-identity"]}},i={schemaVersion:2,revision:2,id:"identity-5",courseId:"identity",locale:"en",title:"Rehearsed enough? Give the real moment a chance",goal:"Use optional brief preparation to address one obstacle, then attempt your same real action.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"If imagining the perfect start keeps replacing the real start, finish preparation with an attempt.",reason:{id:"identity-5-reason",label:"What obstacle would brief rehearsal help you meet?",kind:"text",maxLength:160,optional:!0,suggestions:["Prepare for the actual opening","Try before delivery feels perfect","Keep rehearsal separate from action"]},why:{id:"identity-5-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Rehearsal is preparation, not the action itself. Research on imagining behavior found an average behavioral benefit, but no clear winning type of imagery. It does not prove that imagining the steps beats imagining the outcome, or that a timed identity meditation changes personality.","Use rehearsal if your record shows a preparation gap. Describe or imagine the first step and a likely obstacle. Then try your action at its real cue. If imagery is uncomfortable or unavailable, use words or skip it. Record preparation separately. The attempt can stay awkward, and its outcome remains uncertain."],example:{title:"Leyla's imperfect first line",text:"Before Monday’s report session, Leyla describes how she will start: read her last line, then add one sentence even if it sounds clumsy. She rehearses the transition briefly, with eyes open. At her lunch cue, she adds the sentence. It is less fluent than she imagined. She records the real line separately from the preparation."}},move:{invitation:"If preparation would help, keep it brief. Save the real action as your practice.",instructions:["Rehearse the first useful step only if needed.","Try it at your actual cue; record preparation separately."],prompts:[],suggestions:{action:["Add my next real draft sentence","Use my prepared response once","Complete my chosen practice unit"],minimum:["Write one sentence in the draft","Use one response at the cue","Finish one actual practice unit"],cue:["After lunch when I start writing","At the opening I rehearsed","When my usual cue appears"],place:["In my actual draft","At my usual safe action setting"],fallback:["Skip rehearsal and write one usable sentence","Use words, then try at lunch","Request help with the missing skill"],observation:["What happened in the actual attempt","Whether the expected obstacle appeared","What was only preparation"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Add my next real draft sentence",minimum:"Write one sentence in the draft",minutes:2,cueHint:"After lunch when I start writing",placeHint:"In my actual draft",obstacleHint:"I keep rehearsing instead of starting the actual action.",fallbackHint:"Skip rehearsal and write one usable sentence",observationHint:"What happened in the actual attempt"},stopRule:"Skip trauma scenes. Stop distressing imagery; use words, support, or a safe direct attempt.",accessibleAlternative:"Keep eyes open or skip imagery. For words-only preparation, choose Adapt and name the real-use cue."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-5-decision",scenario:"Leyla knows her first report point and how to enter it. She has ten minutes. Rehearsing a confident session delayed her last two starts.",question:"What best connects preparation with practice?",options:[{id:"identity-5-direct-attempt",text:"Skip further rehearsal, add one sentence at her report cue, and record where starting was actually difficult.",feedback:"Her record identifies expanding rehearsal, not an unclear first step. Trying the known sentence addresses that obstacle. Record any difficulty the real attempt reveals before deciding whether a specific preparation would help."},{id:"identity-5-timed-process",text:"Spend two minutes rehearsing a smooth start, then write one report sentence before the session ends.",feedback:"A timed rehearsal gives preparation an endpoint and may clarify an unfamiliar step. Leyla already knows this step, and rehearsal has delayed two starts. Direct practice tests the problem her record actually identifies."},{id:"identity-5-timed-outcome",text:"Imagine finishing the report for one minute, then write one sentence and record what helped her start.",feedback:"This includes a real attempt, and research establishes no winning imagery subtype. But no motivation gap is identified here. Skipping more imagery responds more directly to Leyla's repeated preparation delay."}],bestOptionId:"identity-5-direct-attempt"}},carry:{takeaway:"Useful rehearsal has an endpoint and a real opportunity beyond it.",followUp:{questionId:"identity-5-return",question:"What differed between your preparation and the actual attempt at your cue?",observationPrompt:"Compare what you prepared with what happened at the cue; skipped preparation is valid.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"No established winning imagery subtype",paragraphs:["Cole and colleagues combined 94 randomized studies, 123 effects, and 5,685 participants [I03]. Mental simulation had an overall behavioral effect of g = 0.49. Some subtype estimates were numerically larger than others, but the overall subtype comparison was not significant. The process-only subgroup contained just five effects and was uncertain.","Most samples were students, and many studies reported limited information about bias. The review does not establish a superior imagery subtype, an advantage from longer practice, or identity change from a ten-minute meditation. This lesson’s brief preparation is a chosen design, not the reviewed protocol.","Choose words, imagery, or no rehearsal according to the actual preparation gap. A description of a useful first step can be easier to inspect than a perfect future scene. The course record should still ask what happened when that step met the real setting."]},{heading:"Prepare the task you will actually do",paragraphs:["Toth and colleagues’ review of 37 studies concerned motor and task performance [I18]. It reported a small bias-adjusted mental-practice effect, r = .131. Motor-task evidence does not establish changed emotional biology, illness recovery, or whole-person identity change. Rehearsal can support a task without replacing instruction, materials, or real practice.","Specific if-then planning has broader goal-attainment support across varied tests [I01]. For this ODA experiment, connect a real cue with the action you already chose, and use rehearsal only to make the response clearer. Preparing your first report sentence and writing it remain different behaviors. Do not infer one from the other.","Skip scenes involving trauma or distressing memories. You can keep your eyes open, describe the steps without pictures, use assistance, or proceed directly to a safe attempt. If preparation keeps expanding, shrink it rather than requiring another morning ritual."]}],sourceIds:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"]}},o={schemaVersion:2,revision:2,id:"identity-6",courseId:"identity",locale:"en",title:"Your cue keeps failing? Change one condition",goal:"Use your records to adjust one cue or material, then test the same useful action.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"A beautiful routine is useless when its cue never happens. Test one condition today.",reason:{id:"identity-6-reason",label:"Which convenience will you change to give this action room?",kind:"text",maxLength:160,optional:!0,suggestions:["Use a cue that actually occurs","Keep the needed material nearby","Protect urgent contact while reducing distraction"]},why:{id:"identity-6-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your attempts. Did the cue occur? Were materials available? A specific plan can fail when its assumed situation never happens. If-then planning helps on average, but the cue needs to fit your week.","Habit research links repeated responses with recurring contexts. Change one condition without declaring your surroundings stronger than your choices. Keep your action. Move its material to the cue, or choose a reliable event. Test once and record where the sequence worked or broke. Preserve access, urgent contact, and routines you need."],example:{title:"Leyla's missing tea cue",text:"Leyla planned to write after afternoon tea, but meetings repeatedly removed that break. She changes only the cue: after returning from lunch, open the report already waiting on her desk and write one sentence. She keeps her phone reachable for family contact. On Tuesday the cue occurs and she writes; the sentence still needs a better ending."}},move:{invitation:"Use one record to change one failed condition. Test your existing action at the revised cue.",instructions:["Choose main and backup events you actually encounter.","Change one cue or material, then try the useful minimum."],prompts:[],suggestions:{action:["Write at my revised start cue","Practice beside the ready material","Use my response at the reliable cue"],minimum:["Add one sentence at this cue","Complete one real practice unit","Use one useful response"],cue:["When I return from lunch","When I finish an essential routine","At my next reliable check-in"],place:["Beside my ready draft","At the accessible action setting"],fallback:["After next meeting: one sentence at my desk","Dictate with available equipment","Keep urgent contact accessible"],observation:["Whether the revised cue occurred","Whether the material was ready","What worked or got in the way"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write at my revised start cue",minimum:"Add one sentence at this cue",minutes:2,cueHint:"When I return from lunch",placeHint:"Beside my ready draft",obstacleHint:"The original cue often does not happen.",fallbackHint:"After next meeting: one sentence at my desk",observationHint:"Whether the revised cue occurred"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-6-decision",scenario:"Leyla’s tea break often disappears. Returning from lunch still happens, and her report can stay ready on her desk.",question:"Which adjustment is worth testing first?",options:[{id:"identity-6-earlier-clock",text:"Keep the tea cue, use a clock reminder to protect that break, and write one sentence afterward.",feedback:"A reminder might help noticing, but it does not make the missing tea break happen. The record identifies cue availability as the problem. Test the reliable return event before adding another reminder."},{id:"identity-6-ready-tea-draft",text:"Keep the tea cue and place the draft beside her mug, then write one sentence after tea.",feedback:"Material placement helps when the draft is hard to reach. Here the break itself keeps disappearing, and the draft can already stay ready. Moving it does not supply the missing cue."},{id:"identity-6-reliable-event",text:"Use the lunch return as the cue, keep the draft ready, and test one useful sentence.",feedback:"This addresses the observed break in the sequence. The action stays the same, and the cue already occurs. Record whether the material was ready and the sentence actually happened."}],bestOptionId:"identity-6-reliable-event"}},carry:{takeaway:"Fix the condition your record identifies. Test before adding more rules.",followUp:{questionId:"identity-6-availability-return",question:"Was your revised cue available?",observationPrompt:"Was the material ready? What worked or got in the way?",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"Specific does not automatically mean feasible",paragraphs:["Gollwitzer and Sheeran’s meta-analysis supports specific situation-response plans on average [I01]. It covered varied goals, samples, and methods, rather than one ideal daily routine. “After tea, write” is specific, but specificity does not make tea a reliable event in your week. Feasibility still needs inspection and an actual attempt.","ODA’s revised-cue experiment changes the condition your own record identifies. If the cue did not occur, test another recognizable event. If the cue occurred but materials were missing, make the materials available. If the action was too large, change its size rather than inventing a motivation problem.","This is one teaching adaptation, not evidence that three obstacle plans or a branded stacking method are necessary. The first chip choices form an editable example plan. They become your commitment only when you choose and save what fits your setting."]},{heading:"Context supports practice without deciding everything",paragraphs:["Wood and Rünger describe repeated responses developing in recurring contexts [I06]. Habitual and deliberate processes can operate together. Their narrative review does not establish a universal ranking in which environment changes always beat effort, or prove that every object silently determines your next choice.","For this experiment, material placement is a practical condition you can inspect. Keep the report near the work surface, or make your communication aid available where the conversation happens. State the trade-off: a phone placed farther away may reduce easy access, but urgent contacts or disability supports may require another arrangement.","Changing one condition makes your next record easier to interpret. A useful outcome might be discovering that the new cue also fails. Keep that fact rather than awarding the setup as completed practice. Preparation can be recorded honestly, and the actual action can be rescheduled or adapted."]}],sourceIds:["identity-gollwitzer","identity-wood-runger"]}},r={schemaVersion:2,revision:2,id:"identity-7",courseId:"identity",locale:"en",title:"Missed days? Build a return that fits",goal:"Review the same experiment and choose a feasible next week of practice, support, or recovery.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The streak broke. Does your next plan serve your life or just repair the number?",reason:{id:"identity-7-reason",label:"Does this experiment still deserve space in your week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the useful part","Shrink the demand to my capacity","Choose recovery without catch-up"]},why:{id:"identity-7-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["The famous 66-day figure estimated how automatic a behavior became. It was not a date when people finished changing. Estimates varied widely, and some extended beyond the study’s observation period. They do not tell you when your action should feel easy.","Review this same experiment: useful action, cue, actual attempts, and the condition needing attention. Choose an opportunity that fits your capacity. Repeat, shrink, seek help, rest, or stop a goal that no longer serves you. Do not add a ritual or catch-up debt to prove you finished the course."],example:{title:"Leyla's smaller return",text:"After an illness, Leyla’s report experiment has three days without attempts. She reviews the sentences she actually wrote and the lunch cue that worked. Still exhausted, she chooses recovery today and a check-in tomorrow. She will decide then whether one sentence fits. She records the pause honestly rather than rewriting the missed days or promising a catch-up session."}},move:{invitation:"Review your same experiment. Choose one appropriate next opportunity or save a pause and return date.",instructions:["Keep the useful action; change only what your records justify.","Choose next week’s size and cue without catch-up debt."],prompts:[],suggestions:{action:["Repeat my useful minimum","Try a smaller meaningful unit","Request support for my experiment"],minimum:["Write one usable sentence","Complete one accessible practice unit","Make one practical support request"],cue:["At my next suitable lunch return","When my capacity allows a safe try","At my chosen support check-in"],place:["At my usual accessible setting","In a safe support conversation"],fallback:["Pause and choose a return date","Shrink the actual practice unit","Ask for help with the constraint"],observation:["Whether the action still served my direction","What fit my current capacity","Which condition helped the return"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Repeat my useful minimum",minimum:"Write one usable sentence",minutes:2,cueHint:"At my next suitable lunch return",placeHint:"At my usual accessible setting",obstacleHint:"I want to compensate for unattempted days.",fallbackHint:"Pause and choose a return date",observationHint:"Whether the action still served my direction"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-7-decision",scenario:"Leyla missed practice while ill and remains exhausted. Her record shows the lunch cue previously worked.",question:"Which next plan respects the evidence and her capacity?",options:[{id:"identity-7-preserve-volume",text:"Use the familiar cue today and write the usual amount more slowly to keep the routine intact.",feedback:"A familiar cue may help when capacity returns, but it does not override exhaustion. The record supports the cue, not today’s usual volume. Recovery and a dated reassessment can be the appropriate choice."},{id:"identity-7-reassess-capacity",text:"Rest today, choose a dated capacity check, and resume a smaller useful action when it fits.",feedback:"This retains the useful experiment without making recovery a failure. It schedules a decision rather than pretending writing occurred. The next attempt should match the capacity she actually has then."},{id:"identity-7-catch-up",text:"Move the missed work to a longer weekend session so this week still meets the original total.",feedback:"A later session can be chosen for a real need, but missed practice creates no scientific catch-up requirement. An enlarged demand may not fit recovery. Reassess capacity before increasing the next action."}],bestOptionId:"identity-7-reassess-capacity"}},carry:{takeaway:"Keep a useful experiment, revise its demands, and return without a deadline for becoming someone new.",followUp:{questionId:"identity-7-return",question:"Did your chosen return fit your capacity and direction, or does the next plan need changing?",observationPrompt:"What fit your capacity and direction, or what needs changing?",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"The famous number was modeled automaticity",paragraphs:["Lally and colleagues followed 96 volunteers choosing eating, drinking, or activity behaviors over 84 days [I04]. There were 82 sufficient-data cases, 62 models, and 39 good fits. In those good-fitting models, time to 95% of the automaticity plateau had a median of 66 days and a range of 18-254 days.","The longer figures were extrapolated beyond observation. The study did not watch everyone “finish a habit,” measure a new personality, or test a rule about two consecutive missed days. One missed opportunity did not materially alter formation in its analysis. That cannot establish a universal recovery rule for longer gaps.","A later review of 20 health-behavior studies also found wide variation [I05]. Only four reported formation times, and 11 studies had high risk of bias. Neither source tells you when writing, listening, or another chosen ODA action must become automatic."]},{heading:"Consolidate the record, not another ritual",paragraphs:["Harkin and colleagues reviewed interventions that increased progress monitoring across 138 randomized studies [I02]. Average goal attainment improved, with a smaller bias-adjusted estimate. Methods and goals varied. The review does not show that a fifteen-minute weekly review, a streak, or a future-self letter is the optimal format.","This course’s consolidation is an ODA design choice. Read the records for the same experiment, distinguish real attempts from plans and pauses, and identify the condition worth keeping. A future plan creates no completed behavior. Missing records stay unknown until you report what happened.","Choose next week’s action size and a recognizable cue only if the experiment still serves your direction. Support, recovery, a boundary, or stopping can be deliberate responses. Keep their names accurate. You do not need a new identity statement, a longer session, or compensation for missed days to make a thoughtful return."]}],sourceIds:["identity-lally","identity-habit-times","identity-harkin"]}},c={id:"identity",title:"Keep slipping back? Change one pattern this week",subtitle:"Seven lessons to find a recurring cue, try a useful response, and improve it from real attempts.",description:"Choose one pattern that crowds out something you want. Try a meaningful response, record the actual result, and refine the cue, preparation, or support that helps it fit your life.",outcome:"One meaningful action, a tested cue, and an honest return plan that fits your actual week.",scope:"For adults who want an everyday way to change a familiar pattern of thinking, feeling or reacting. It draws on Dr. Joe Dispenza and James Clear and says plainly which of their ideas research supports and which it does not. It is not therapy and not a treatment for depression, anxiety, trauma or any illness; if you are struggling, talk to a health professional, and in a crisis call your local emergency number.",photo:{id:"1611569518992-0927098278b7",alt:"A woman walking alone down a dirt road between green trees"},lessons:[{id:"identity-1",schemaVersion:2,v2:e,title:"Still scrolling? Find your changeable moment",minutes:6,goal:"Choose one recurring cue and try a useful response that serves your week.",reading:["A familiar setting can cue a familiar action, even after your priorities change. Habit research separates that repeated response from your whole personality. “After lunch, I scroll before starting” names a pattern. “I am lazy” gives you no moment to work with.","Choose one ordinary cue and one useful alternative. Notice what the old response offers now and what it postpones. Then try the alternative once. This course keeps improving that same experiment. You can start with a small act without rejecting who you are or promising a new personality."],practice:["Choose one familiar cue. Try a response that does something useful for your chosen direction.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What does this pattern protect now and postpone later?",question:"Leyla planned to write after lunch but scrolled. She has five minutes and the report open. Which move starts a useful experiment?",options:["Build a stricter afternoon schedule, then begin the report once the new schedule is complete.","Name what happened after lunch, then write one report sentence and record the cue.","Move tomorrow’s writing before lunch and use today’s remaining five minutes to review the new plan."],correct:1,feedback:"This tests a response in the real setting. The sentence does useful work, and the note identifies the cue. One attempt provides information without proving a whole personality change.",takeaway:"Change one response in one setting. Let the record describe what happened.",sources:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"],deeper:[{heading:"A pattern is smaller than a person",paragraphs:["Wood and Rünger’s review describes habits as repeated responses associated with recurring contexts [I06]. A setting can call up a familiar response alongside deliberate choices. That is a narrower claim than saying every thought, mood, or difficult day is an automatic program. This lesson asks about one observable behavior, not an “old self” that must be removed.","The diary research used student samples of 70 and 209 people [I07]. Respectively, 35% and 43% of their reports met an almost-daily, same-location definition of habit. Those figures do not describe all adults, and they are not percentages of time spent mind-wandering. Sampling behavior was assessment, not a demonstrated identity treatment.","ODA’s cue-and-response note is a teaching adaptation. Keep only the detail useful for your next choice. An unchanged mood or imperfect afternoon does not invalidate an accurately reported attempt."]},{heading:"Make the alternative consequential",paragraphs:["Gollwitzer and Sheeran’s review combined 94 independent tests involving 8,461 participants [I01]. It found an average goal-attainment benefit from specific if-then plans. The evidence included 83 experimental and 11 correlational tests, with varied goals and methods. It does not establish that this particular ODA sequence changes identity.","For this experiment, connect a recognizable event with a feasible response: when you return after lunch, write one useful report sentence. Specify a cue you actually encounter. Choose an alternative that contributes to your direction, rather than simply opening an app or arranging supplies. Those may be preparation, but the practice should be named accurately.","There is no requirement to interrupt every familiar behavior. Keep routines that serve your life. If the setting calls for safety, rest, or assistance, choose that response deliberately. Review this one attempt before adding another system."]}],example:{title:"Leyla's first report sentence",text:"At 1:30, Leyla returns to her desk and reaches for her phone before writing a report. She wants fewer late evenings. She puts the phone aside and writes one rough opening sentence instead. The wording is awkward, and she later scrolls again. Her record says what she did at the cue, without calling the afternoon a transformation."},photo:{id:"1519087630026-63fb0dab69bb",alt:"A woman looking at her reflection in a wall mirror"}},{id:"identity-2",schemaVersion:2,v2:t,title:"Worry still here? Choose your response anyway",minutes:6,goal:"Use your same cue to do the useful action while an ordinary feeling remains.",reading:["Bring back your cue and action. A familiar feeling is something to notice, not proof of a fixed personality. Naming feelings has a narrow research basis: one small study found a changed brain response when people labeled emotions on faces. It did not test whether your own worry disappears.","Use a label as a description: “Worry is here.” Check whether it points to a real need, then choose your response. You may write your sentence while worried, or seek help if the concern needs action. The useful act counts without a calmer feeling afterward."],practice:["Keep your experiment. Name an ordinary feeling if useful, then do the chosen response.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What is waiting for this feeling costing your direction?",question:"Leyla has five minutes. Her figures match the approved table, and her sentence makes no new calculation. She still feels worried. Which response fits this moment?",options:["Recheck the figures once more so she can feel more certain before writing the sentence.","Draft a provisional sentence and ask a colleague to verify its figure before keeping the line in the report.","Name the worry, write one usable sentence, and record whether the concern needed further action."],correct:2,feedback:"This preserves the feeling and checks its meaning without giving it an automatic veto. The sentence is the practice. If a real concern appears, her next response can be practical help.",takeaway:"A feeling can remain while you choose a useful, safe response.",sources:["identity-lieberman","identity-breines"],deeper:[{heading:"What labeling actually measured",paragraphs:["Lieberman and colleagues studied 30 healthy adults looking at emotional faces in a brain scanner [I10]. Choosing an emotion word produced lower amygdala activation than choosing a gender-matched name. That is a difference in a laboratory brain measure, not a finding that naming your own distress makes it smaller or improves mood for weeks.","ODA uses a short feeling label as optional description. The study did not test this cue, your chosen behavior, or a course about identity. Skip labeling if it adds nothing, and avoid turning every emotion into something you must correct. Grief, anger about unfairness, and fear in danger can deserve a different response.","Bring the observation back to the same action. Did you do it, did you need assistance, or did a real problem change the plan? A record can hold a difficult feeling and a useful behavior without claiming one caused the other."]},{heading:"Support without removing accountability",paragraphs:["Breines and Chen tested compassionate responses in four short experiments, mainly with student or online samples [I11]. Some outcomes supported immediate improvement motivation. In one study, participants spent more time studying after a difficult test than those receiving no intervention. Their later test scores did not significantly differ, and comparison with a self-esteem condition was only marginal.","That evidence does not prove lasting identity change or universal superiority of kindness. It does challenge the assumption that a harsh response is always needed before trying again. This lesson’s instruction to describe a feeling and continue a chosen action is an ODA adaptation, not the tested compassionate-writing procedure.","Use a fair response that keeps responsibility visible. A missing skill calls for learning; an unmet need may call for help. You can act without insulting yourself and can pause without calling the pause a failed personality."]}],example:{title:"Leyla's worried start",text:"After lunch on Thursday, Leyla feels worried about the same report. She checks that she has the required figures, names the worry, and writes her next usable sentence. She still wants to recheck everything. She records the sentence and that the worry stayed. She has practiced writing, not proved that the feeling is a habit."},photo:{id:"1762126242240-cafa01fb1351",alt:"A person in an armchair looking out of a rainy window"}},{id:"identity-3",schemaVersion:2,v2:a,title:"Caught yourself late? Make the next move useful",minutes:6,goal:"Return to your chosen action after a distraction, or repair a response that caused harm.",reading:["Noticing a distraction is different from returning. Keep your chosen cue and action. Add a late-catch response: “If I notice I have drifted, I will do my useful minimum.” Specific cue-and-action plans have improved goal attainment on average in research.","If your response hurt someone, a private catch is not the repair. In a safe setting, acknowledge your part and restart one sentence. If nobody was harmed, return to the task. Record the response, not just notices. You can change the next act without declaring the day ruined."],practice:["Keep your action. Choose what you will do when you notice the pattern late.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What needs a return or repair in this same experiment?",question:"During a safe discussion, Leyla snaps at a colleague. She notices her tone while they are still talking. What best completes the interruption?",options:["Acknowledge the sharp sentence and restate her point respectfully while the conversation is still open.","Pause privately and record the catch, then focus on speaking more patiently in their next discussion.","Explain why the deadline pressure caused her tone, then return to the work discussion without revisiting it."],correct:0,feedback:"This makes the catch consequential. Leyla takes responsibility for her own tone and practices a different response. The colleague does not have to forgive her for the repair attempt to be real.",takeaway:"A catch becomes useful when you return, repair, or choose a safer response.",sources:["identity-gollwitzer","identity-wood-runger","identity-harkin"],deeper:[{heading:"A cue can include late noticing",paragraphs:["Implementation intentions connect a specific situation with a chosen response. Gollwitzer and Sheeran’s synthesis found an average benefit for goal attainment across 94 independent tests [I01]. Goals, delivery, and study methods varied. It does not validate a particular pause word, breathing sequence, or number of daily catches.","This lesson adds late noticing as another possible situation: if you notice scrolling has begun, write your chosen useful sentence. The response is still the same course experiment. A silent cue word is optional shorthand, not the active behavior you are trying to build. No breath or calm feeling is required before returning.","Wood and Rünger describe habits operating alongside deliberate processes [I06]. That leaves room for an intentional response within an imperfect routine. It does not mean every distraction was a habit. Describe what you observed and test whether this cue is recognizable in your actual setting."]},{heading:"Notice, then respond to the consequence",paragraphs:["A record should distinguish noticing, returning, and repairing. Harkin and colleagues reviewed 138 randomized progress-monitoring studies [I02]. Monitoring interventions improved goal attainment on average, though a bias-adjusted estimate was smaller. The review does not establish that counting catches alone changes your relationships or that every private note needs to be shared.","For this ODA adaptation, record the behavior that followed your notice. “I caught my sharp tone” and “I acknowledged it and restated my request” are different facts. If your original task was interrupted, record the useful part you resumed. If you caused no harm, an apology is not required.","Protection takes priority in an unsafe relationship. You do not owe contact, forgiveness, or an explanation to someone who threatens you. Choose a boundary or support step when it fits. Keep those acts named accurately rather than treating every pause as successful repair."]}],example:{title:"Leyla's late catch",text:"At 1:42, Leyla notices she has spent twelve minutes scrolling instead of writing. She closes the feed and adds one useful sentence to her report. Later she notices an abrupt message she sent her colleague. She sends a brief correction of her tone. Neither act erases the lost time, but both are specific responses she can record."},photo:{id:"1626257690705-8d62125575b0",alt:"A man in a dark jacket walking along a city pedestrian lane in daylight"}},{id:"identity-4",schemaVersion:2,v2:n,title:"Busy preparing? Make your next action real proof",minutes:6,goal:"Check that your minimum practices the behavior your direction needs, then do it once.",reading:["Bring back your last attempt. James Clear calls actions “votes” for an identity. That is a metaphor, not a scientific law. You can use it without saying your identity must change first. The useful question is whether this action practices something your direction needs.","Opening a draft proves you opened it. Writing one usable sentence proves you wrote. Both can have a purpose, but name preparation as preparation. Keep the minimum small enough for your week and substantial enough to matter. After an actual attempt, describe only that evidence. “I wrote a sentence” needs no claim about permanent confidence."],practice:["Check your saved minimum. If it only prepares, name that honestly or choose actual practice.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Is this minimum building the skill or postponing it?",question:"Leyla has five tired minutes and wants report text. Her headings are ready; the next sentence's figure already matches its source. Which minimum does useful work now?",options:["Arrange the notes into a clearer folder so tomorrow’s writing session starts with less friction.","Write one rough sentence in the real report, then decide whether stopping fits her capacity.","Recheck the cited figure against its source, then leave a verified note for tomorrow's sentence."],correct:1,feedback:"This minimum practices the desired behavior and respects the time available. It proves one sentence was written, not that her identity changed. She can stop without making the sentence impressive.",takeaway:"Let your evidence name the behavior. Keep preparation and practice distinct.",sources:["identity-clear-identity","identity-task-belief","identity-activity-identity"],deeper:[{heading:"An identity metaphor has limits",paragraphs:["Clear’s author article presents a desired identity and small supporting actions as a practitioner framework [I15]. It is not a controlled trial proving identity-first change is required or superior. The familiar action-as-vote framing can be memorable without becoming a scientific explanation.","Bandura’s self-efficacy framework concerns perceived capability for a particular task [I17]. Mastery experiences are one source of that belief, alongside observation, persuasion, and physiological information. The framework does not turn one action into a measure of your worth or a verdict about your whole personality.","ODA’s optional evidence statement stays narrow: “I added a usable sentence” or “I made my request.” An untried plan and a correct quiz answer do not establish those behaviors. You may leave identity language out entirely while continuing the same practical experiment."]},{heading:"Behavior and identity are different outcomes",paragraphs:["Rhodes and colleagues reviewed 40 experimental or quasi-experimental effects involving 4,939 adults [I19]. Physical-activity identity changed a little on average, with an effect of g = 0.18. A 30-effect behavior subsample showed a larger average activity effect, but the samples and outcomes differ. Those numbers do not prove identity caused behavior change.","The studies concern physical activity, with heterogeneous results and possible publication bias. They do not validate broad personality transformation, Clear’s vote method, or this report-writing experiment. Difficulty also does not automatically show that a goal matters enough to pursue. It can reveal a missing skill, insufficient resources, or a need to revise the plan.","Use the record to decide what your minimum contributes. Keep a small unit when it fits capacity, increase it only by choice, or change an unsuitable goal. The aim is useful practice in your life, not collecting symbolic votes."]}],example:{title:"Leyla's useful minimum",text:"On Friday, Leyla spends five minutes arranging headings but has written no report text. She checks her experiment and changes the minimum to one usable sentence under a heading. She writes it before stopping. The sentence needs editing. Her optional note says, “I wrote a sentence today,” rather than “I am now a disciplined person.”"},photo:{id:"1787154604447-4a62ed6654e3",alt:"A woman in a dark hijab and sports clothes jogging along a city street"}},{id:"identity-5",schemaVersion:2,v2:i,title:"Rehearsed enough? Give the real moment a chance",minutes:6,goal:"Use optional brief preparation to address one obstacle, then attempt your same real action.",reading:["Rehearsal is preparation, not the action itself. Research on imagining behavior found an average behavioral benefit, but no clear winning type of imagery. It does not prove that imagining the steps beats imagining the outcome, or that a timed identity meditation changes personality.","Use rehearsal if your record shows a preparation gap. Describe or imagine the first step and a likely obstacle. Then try your action at its real cue. If imagery is uncomfortable or unavailable, use words or skip it. Record preparation separately. The attempt can stay awkward, and its outcome remains uncertain."],practice:["If preparation would help, keep it brief. Save the real action as your practice.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What obstacle would brief rehearsal help you meet?",question:"Leyla knows her first report point and how to enter it. She has ten minutes. Rehearsing a confident session delayed her last two starts. What best connects preparation with practice?",options:["Skip further rehearsal, add one sentence at her report cue, and record where starting was actually difficult.","Spend two minutes rehearsing a smooth start, then write one report sentence before the session ends.","Imagine finishing the report for one minute, then write one sentence and record what helped her start."],correct:0,feedback:"Her record identifies expanding rehearsal, not an unclear first step. Trying the known sentence addresses that obstacle. Record any difficulty the real attempt reveals before deciding whether a specific preparation would help.",takeaway:"Useful rehearsal has an endpoint and a real opportunity beyond it.",sources:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"],deeper:[{heading:"No established winning imagery subtype",paragraphs:["Cole and colleagues combined 94 randomized studies, 123 effects, and 5,685 participants [I03]. Mental simulation had an overall behavioral effect of g = 0.49. Some subtype estimates were numerically larger than others, but the overall subtype comparison was not significant. The process-only subgroup contained just five effects and was uncertain.","Most samples were students, and many studies reported limited information about bias. The review does not establish a superior imagery subtype, an advantage from longer practice, or identity change from a ten-minute meditation. This lesson’s brief preparation is a chosen design, not the reviewed protocol.","Choose words, imagery, or no rehearsal according to the actual preparation gap. A description of a useful first step can be easier to inspect than a perfect future scene. The course record should still ask what happened when that step met the real setting."]},{heading:"Prepare the task you will actually do",paragraphs:["Toth and colleagues’ review of 37 studies concerned motor and task performance [I18]. It reported a small bias-adjusted mental-practice effect, r = .131. Motor-task evidence does not establish changed emotional biology, illness recovery, or whole-person identity change. Rehearsal can support a task without replacing instruction, materials, or real practice.","Specific if-then planning has broader goal-attainment support across varied tests [I01]. For this ODA experiment, connect a real cue with the action you already chose, and use rehearsal only to make the response clearer. Preparing your first report sentence and writing it remain different behaviors. Do not infer one from the other.","Skip scenes involving trauma or distressing memories. You can keep your eyes open, describe the steps without pictures, use assistance, or proceed directly to a safe attempt. If preparation keeps expanding, shrink it rather than requiring another morning ritual."]}],example:{title:"Leyla's imperfect first line",text:"Before Monday’s report session, Leyla describes how she will start: read her last line, then add one sentence even if it sounds clumsy. She rehearses the transition briefly, with eyes open. At her lunch cue, she adds the sentence. It is less fluent than she imagined. She records the real line separately from the preparation."},photo:{id:"1600618528240-fb9fc964b853",alt:"A woman meditating on a wooden deck at sunset"}},{id:"identity-6",schemaVersion:2,v2:o,title:"Your cue keeps failing? Change one condition",minutes:6,goal:"Use your records to adjust one cue or material, then test the same useful action.",reading:["Bring back your attempts. Did the cue occur? Were materials available? A specific plan can fail when its assumed situation never happens. If-then planning helps on average, but the cue needs to fit your week.","Habit research links repeated responses with recurring contexts. Change one condition without declaring your surroundings stronger than your choices. Keep your action. Move its material to the cue, or choose a reliable event. Test once and record where the sequence worked or broke. Preserve access, urgent contact, and routines you need."],practice:["Use one record to change one failed condition. Test your existing action at the revised cue.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Which convenience will you change to give this action room?",question:"Leyla’s tea break often disappears. Returning from lunch still happens, and her report can stay ready on her desk. Which adjustment is worth testing first?",options:["Keep the tea cue, use a clock reminder to protect that break, and write one sentence afterward.","Keep the tea cue and place the draft beside her mug, then write one sentence after tea.","Use the lunch return as the cue, keep the draft ready, and test one useful sentence."],correct:2,feedback:"This addresses the observed break in the sequence. The action stays the same, and the cue already occurs. Record whether the material was ready and the sentence actually happened.",takeaway:"Fix the condition your record identifies. Test before adding more rules.",sources:["identity-gollwitzer","identity-wood-runger"],deeper:[{heading:"Specific does not automatically mean feasible",paragraphs:["Gollwitzer and Sheeran’s meta-analysis supports specific situation-response plans on average [I01]. It covered varied goals, samples, and methods, rather than one ideal daily routine. “After tea, write” is specific, but specificity does not make tea a reliable event in your week. Feasibility still needs inspection and an actual attempt.","ODA’s revised-cue experiment changes the condition your own record identifies. If the cue did not occur, test another recognizable event. If the cue occurred but materials were missing, make the materials available. If the action was too large, change its size rather than inventing a motivation problem.","This is one teaching adaptation, not evidence that three obstacle plans or a branded stacking method are necessary. The first chip choices form an editable example plan. They become your commitment only when you choose and save what fits your setting."]},{heading:"Context supports practice without deciding everything",paragraphs:["Wood and Rünger describe repeated responses developing in recurring contexts [I06]. Habitual and deliberate processes can operate together. Their narrative review does not establish a universal ranking in which environment changes always beat effort, or prove that every object silently determines your next choice.","For this experiment, material placement is a practical condition you can inspect. Keep the report near the work surface, or make your communication aid available where the conversation happens. State the trade-off: a phone placed farther away may reduce easy access, but urgent contacts or disability supports may require another arrangement.","Changing one condition makes your next record easier to interpret. A useful outcome might be discovering that the new cue also fails. Keep that fact rather than awarding the setup as completed practice. Preparation can be recorded honestly, and the actual action can be rescheduled or adapted."]}],example:{title:"Leyla's missing tea cue",text:"Leyla planned to write after afternoon tea, but meetings repeatedly removed that break. She changes only the cue: after returning from lunch, open the report already waiting on her desk and write one sentence. She keeps her phone reachable for family contact. On Tuesday the cue occurs and she writes; the sentence still needs a better ending."},photo:{id:"1675762647949-1b25f669a687",alt:"A pair of white shoes sitting on a wooden floor"}},{id:"identity-7",schemaVersion:2,v2:r,title:"Missed days? Build a return that fits",minutes:6,goal:"Review the same experiment and choose a feasible next week of practice, support, or recovery.",reading:["The famous 66-day figure estimated how automatic a behavior became. It was not a date when people finished changing. Estimates varied widely, and some extended beyond the study’s observation period. They do not tell you when your action should feel easy.","Review this same experiment: useful action, cue, actual attempts, and the condition needing attention. Choose an opportunity that fits your capacity. Repeat, shrink, seek help, rest, or stop a goal that no longer serves you. Do not add a ritual or catch-up debt to prove you finished the course."],practice:["Review your same experiment. Choose one appropriate next opportunity or save a pause and return date.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Does this experiment still deserve space in your week?",question:"Leyla missed practice while ill and remains exhausted. Her record shows the lunch cue previously worked. Which next plan respects the evidence and her capacity?",options:["Use the familiar cue today and write the usual amount more slowly to keep the routine intact.","Rest today, choose a dated capacity check, and resume a smaller useful action when it fits.","Move the missed work to a longer weekend session so this week still meets the original total."],correct:1,feedback:"This retains the useful experiment without making recovery a failure. It schedules a decision rather than pretending writing occurred. The next attempt should match the capacity she actually has then.",takeaway:"Keep a useful experiment, revise its demands, and return without a deadline for becoming someone new.",sources:["identity-lally","identity-habit-times","identity-harkin"],deeper:[{heading:"The famous number was modeled automaticity",paragraphs:["Lally and colleagues followed 96 volunteers choosing eating, drinking, or activity behaviors over 84 days [I04]. There were 82 sufficient-data cases, 62 models, and 39 good fits. In those good-fitting models, time to 95% of the automaticity plateau had a median of 66 days and a range of 18-254 days.","The longer figures were extrapolated beyond observation. The study did not watch everyone “finish a habit,” measure a new personality, or test a rule about two consecutive missed days. One missed opportunity did not materially alter formation in its analysis. That cannot establish a universal recovery rule for longer gaps.","A later review of 20 health-behavior studies also found wide variation [I05]. Only four reported formation times, and 11 studies had high risk of bias. Neither source tells you when writing, listening, or another chosen ODA action must become automatic."]},{heading:"Consolidate the record, not another ritual",paragraphs:["Harkin and colleagues reviewed interventions that increased progress monitoring across 138 randomized studies [I02]. Average goal attainment improved, with a smaller bias-adjusted estimate. Methods and goals varied. The review does not show that a fifteen-minute weekly review, a streak, or a future-self letter is the optimal format.","This course’s consolidation is an ODA design choice. Read the records for the same experiment, distinguish real attempts from plans and pauses, and identify the condition worth keeping. A future plan creates no completed behavior. Missing records stay unknown until you report what happened.","Choose next week’s action size and a recognizable cue only if the experiment still serves your direction. Support, recovery, a boundary, or stopping can be deliberate responses. Keep their names accurate. You do not need a new identity statement, a longer session, or compensation for missed days to make a thoughtful return."]}],example:{title:"Leyla's smaller return",text:"After an illness, Leyla’s report experiment has three days without attempts. She reviews the sentences she actually wrote and the lunch cue that worked. Still exhausted, she chooses recovery today and a check-in tomorrow. She will decide then whether one sentence fits. She records the pause honestly rather than rewriting the missed days or promising a catch-up session."},photo:{id:"1760715160644-7f5939675b68",alt:"Hikers walking along a trail through a golden meadow"}}]};export{c as COURSE,e as IDENTITY_1_V2,t as IDENTITY_2_V2,a as IDENTITY_3_V2,n as IDENTITY_4_V2,i as IDENTITY_5_V2,o as IDENTITY_6_V2,r as IDENTITY_7_V2,s as SOURCES};
